137	fn complete_arg(
138	    arg: &clap_lex::ParsedArg<'_>,
139	    cmd: &clap::Command,
140	    current_dir: Option<&std::path::Path>,
141	    pos_index: usize,
142	    is_escaped: bool,
143	    state: ParseState<'_>,
144	    used_args: &[clap::Id],
145	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
146	    debug!(
147	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
148	        arg,
149	        cmd.get_name(),
150	        current_dir,
151	        pos_index,
152	        state
153	    );
154	    let mut completions = Vec::<CompletionCandidate>::new();
155	
156	    match state {
157	        ParseState::ValueDone => {
158	            if !is_escaped {
159	                if let Ok(value) = arg.to_value() {
160	                    completions.extend(complete_subcommand(value, cmd));
161	                }
162	            }
163	
164	            if let Some(positional) = cmd
165	                .get_positionals()
166	                .find(|p| p.get_index() == Some(pos_index))
167	            {
168	                completions.extend(complete_arg_value(
169	                    arg.to_value(),
170	                    positional,
171	                    current_dir,
172	                    0,
173	                ));
174	            }
175	            if !is_escaped {
176	                completions.extend(complete_option(arg, cmd, current_dir));
177	            }
178	        }
179	        ParseState::Pos((_, num_arg)) => {
180	            if let Some(positional) = cmd
181	                .get_positionals()
182	                .find(|p| p.get_index() == Some(pos_index))
183	            {
184	                completions.extend(complete_arg_value(
185	                    arg.to_value(),
186	                    positional,
187	                    current_dir,
188	                    num_arg.saturating_sub(1),
189	                ));
190	                if !is_escaped
191	                    && positional
192	                        .get_num_args()
193	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
194	                {
195	                    completions.extend(complete_option(arg, cmd, current_dir));
196	                }
197	            }
198	        }
199	        ParseState::Opt((opt, count)) => {
200	            completions.extend(complete_arg_value(
201	                arg.to_value(),
202	                opt,
203	                current_dir,
204	                count.saturating_sub(1),
205	            ));
206	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
207	            if count > min {
208	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
209	                completions.extend(complete_arg(
210	                    arg,
211	                    cmd,
212	                    current_dir,
213	                    pos_index,
214	                    is_escaped,
215	                    ParseState::ValueDone,
216	                    used_args,
217	                )?);
218	            }
219	        }
220	    }
221	    filter_conflicting_candidates(&mut completions, cmd, used_args);
222	    if completions.iter().any(|a| !a.is_hide_set()) {
223	        completions.retain(|a| !a.is_hide_set());
224	    }
225	    let mut seen_ids = std::collections::HashSet::new();
226	    completions.retain(move |a| {
227	        if let Some(id) = a.get_id().cloned() {
228	            seen_ids.insert(id)
229	        } else {
230	            true
231	        }
232	    });
233	
234	    let mut tags = Vec::new();
235	    for candidate in &completions {
236	        let tag = candidate.get_tag().cloned();
237	        if !tags.contains(&tag) {
238	            tags.push(tag);
239	        }
240	    }
241	    completions.sort_by_key(|c| {
242	        (
243	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
244	            c.get_display_order(),
245	        )
246	    });
247	
248	    Ok(completions)
249	}
