1870	fn complete(cmd: &mut Command, args: impl AsRef<str>, current_dir: Option<&Path>) -> String {
1871	    let input = args.as_ref();
1872	    let mut args = vec![std::ffi::OsString::from(cmd.get_name())];
1873	    let arg_index;
1874	
1875	    if let Some((prior, after)) = input.split_once("[TAB]") {
1876	        args.extend(prior.split_whitespace().map(From::from));
1877	        if prior.ends_with(char::is_whitespace) {
1878	            args.push(std::ffi::OsString::default());
1879	        }
1880	        arg_index = args.len() - 1;
1881	        // HACK: this cannot handle in-word '[TAB]'
1882	        args.extend(after.split_whitespace().map(From::from));
1883	    } else {
1884	        args.extend(input.split_whitespace().map(From::from));
1885	        if input.ends_with(char::is_whitespace) {
1886	            args.push(std::ffi::OsString::default());
1887	        }
1888	        arg_index = args.len() - 1;
1889	    }
1890	
1891	    clap_complete::engine::complete(cmd, args, arg_index, current_dir)
1892	        .unwrap()
1893	        .into_iter()
1894	        .map(|candidate| {
1895	            let compl = candidate.get_value().to_str().unwrap();
1896	            if let Some(help) = candidate.get_help() {
1897	                format!("{compl}\t{help}")
1898	            } else {
1899	                compl.to_owned()
1900	            }
1901	        })
1902	        .collect::<Vec<_>>()
